        error(string.format("expected %s but found '%s' here:\n%s",what,value,
              text:sub(1,pos).."<--##    "..text:sub(pos+1,-1)))
    end
    local function skip(pattern)
        local matched = text:match(pattern,pos)
        pos = pos + #matched
        if pos <= #text then
            return false
        end
        cur,value = "EOF","EOF"
        return true
