    return function(vs)
        if not List:isclassof(vs) then return false end
        local node = listcache
        for i,e in ipairs(vs) do
            if not checkt(e) then return false,i end
            local next = node[e]
            if not next then
                next = {}
                node[e] = next
            end
            node = next
        end
        local r = node[valuekey]
        if not r then
            r = vs
            node[valuekey] = r
        end
        return true,r
    end
end

