            local captured=environment[definition]
            if captured then return captured end
            -- `let y = x` is an alias of the same value, so a use of `y` constrains `x`.
            local value=initializer[definition]
            if value and #value.items==0 and A.Data:isclassof(value.terminal) then
                return infer(value.terminal.value,expected)
            end
            return nil
        end
        if A.Move:isclassof(expr) then return infer(expr.place,expected) end
        if A.Unary:isclassof(expr) then
            local operator=expr.operator
            if operator==A.Not then infer(expr.operand,B.Bool); return B.Bool end
            if operator==A.BitNot then infer(expr.operand,B.Int); return B.Int end
            if operator==A.ToFloat then infer(expr.operand,B.Int); return B.Float end
            if operator==A.ToInt then infer(expr.operand,B.Float); return B.Int end
            if operator==A.ToU8 then infer(expr.operand,B.Int); return B.U8 end
            if operator==A.ToU32 then infer(expr.operand,B.Int); return B.U32 end
            if operator==A.ToF32 then infer(expr.operand,B.Float); return B.Float32 end
            -- Negate: the operand has the expression's type.
            local type_=infer(expr.operand,expected)
            if type_ then return type_ end
            if numeric(expected) then infer(expr.operand,expected); return expected end
            return nil
        end
        if A.Binary:isclassof(expr) then
            local operator=expr.operator
            if operator==A.BitAnd or operator==A.BitOr or operator==A.BitXor
                or operator==A.ShiftLeft or operator==A.ShiftRight then
                infer(expr.left,B.Int); infer(expr.right,B.Int); return B.Int
            end
            if operator==A.And or operator==A.Or then
                infer(expr.left,B.Bool); infer(expr.right,B.Bool); return B.Bool
            end
            if operator==A.Equal or operator==A.NotEqual then
                local type_=expected or infer(expr.left,nil) or infer(expr.right,nil)
                if type_ then infer(expr.left,type_); infer(expr.right,type_) end
                return B.Bool
            end
            -- Comparison and arithmetic both require one numeric type on both sides.
            local type_=(numeric(expected) and expected) or infer(expr.left,nil) or infer(expr.right,nil)
            if type_ and numeric(type_) then infer(expr.left,type_); infer(expr.right,type_) end
            if operator==A.Less or operator==A.LessEqual or operator==A.Greater or operator==A.GreaterEqual then
                return B.Bool
            end
            return type_ and numeric(type_) and type_ or nil
        end
        -- A record the surrounding type already describes: each member takes the member type.
        if A.PositionalAggregate:isclassof(expr) then
            local wanted=expected and expected:record()
            local declared,complete,copy=L(),true,true
            for i,element in ipairs(expr.elements) do
                local type_=chain(element,wanted and wanted[i] and wanted[i].type)
                if not type_ then complete=false
                else
                    declared:insert(B.Field(nil,type_,false))
                    if not type_:copyable() then copy=false end
                end
            end
            if not complete then return nil end
            return B.Aggregate(declared,copy,nil)
        end
        if A.NamedAggregate:isclassof(expr) then
            local wanted=expected and expected:record()
            local declared,complete,copy=L(),true,true
            for _,member in ipairs(expr.members) do
                local member_type
                if wanted then for _,field in ipairs(wanted) do if field.name==member.name then member_type=field.type end end end
                local type_=constraint_type(types,member.constraint) or chain(member.value,member_type)
                if not type_ then complete=false
                else
                    declared:insert(B.Field(member.name,type_,member.mutable))
                    if member.mutable or not type_:copyable() then copy=false end
                end
            end
            if not complete then return nil end
            return B.Aggregate(declared,copy,nil)
        end
        if A.Project:isclassof(expr) then
            local base=infer(expr.base,nil)
            local fields=base and base:record()
            if fields then
                for _,field in ipairs(fields) do if field.name==expr.name then return field.type end end
            end
            return nil
        end
        if A.Index:isclassof(expr) then
            local base=infer(expr.base,nil)
            local fields=base and base:record()
            if not fields then return nil end
            local index=static_index(expr.index)
            if index then
                local field=fields[index+1]
                return field and field.type or nil
            end
            -- A run-time index yields one value, so the members must share one type.
            infer(expr.index,B.Int)
            local element=fields[1] and fields[1].type
            for i=2,#fields do if not fields[i].type:same(element) then return nil end end
            return element
        end
        -- A named callee: a conversion, a registered host, or a word whose contract types the
        -- arguments. A word's own result type is known when its contract could compute one.
        if A.Invoke:isclassof(expr) and A.Name:isclassof(expr.word) then
            local definition=definition_of(resolved,expr.word)
            if definition and definition.kind=='dictionary' then
                -- The core conversions (§13.3) fix their argument and their result.
                if definition.name=='float' then infer(expr.arguments[1],B.Int); return B.Float end
                if definition.name=='int' then infer(expr.arguments[1],B.Float); return B.Int end
                local host=definition.node
                local signature=host and host.signature
                if signature then
                    for i,argument in ipairs(expr.arguments) do
                        local parameter=signature.parameters[i]
                        if parameter then infer(argument,parameter.type) end
                    end
                    return signature.results[1]
                end
                return nil
            end
            local callee=callee_template(definition)
            if not callee then return nil end
            local contract=Contract.template(callee,resolved,types,nil)
            for i,argument in ipairs(expr.arguments) do infer(argument,callee_stage(callee,contract,i)) end
            return contract.result
        end
        -- Juxtaposition: a conversion, or the next stage of a word. The result is the more
        -- specific word value, whose type this pass does not model.
        if A.Specialize:isclassof(expr) and A.Name:isclassof(expr.word) then
            local definition=definition_of(resolved,expr.word)
            if definition and definition.kind=='dictionary' then
                if definition.name=='float' then infer(expr.argument,B.Int); return B.Float end
                if definition.name=='int' then infer(expr.argument,B.Float); return B.Int end
                return nil
            end
            local callee=callee_template(definition)
            if callee then
                local contract=Contract.template(callee,resolved,types,nil)
                infer(expr.argument,callee_stage(callee,contract,1))
            end
            return nil
        end
        return nil
    end

    function chain(chain,expected)
        if chain and #chain.items==0 and A.Data:isclassof(chain.terminal) then
            return infer(chain.terminal.value,expected)
        end
        return nil
    end

    -- A return states the result type. Every return must agree; one the pass cannot type is
    -- simply absent, and a returned self-call is the case that stays unknown.
    local function returned(statement)
        returns=returns+1
        local type_
        if statement.value then type_=infer(statement.value,nil) else type_=B.Unit end
        if type_ then
            if stated==nil then stated=type_
            elseif not stated:same(type_) then conflict=true end
        end
    end

    statements=function(list)
        for _,statement in ipairs(list) do
            if A.Local:isclassof(statement) then
                infer_binding(statement.binding); chain(statement.binding.value,constraint_type(types,statement.binding.constraint))
            elseif A.Assign:isclassof(statement) then
                -- The place's type is the expectation for the value, which is how `y = x`
                -- constrains a stage `x` once `y` is typed.
                local place_type=A.Name:isclassof(statement.place) and infer(statement.place,nil) or nil
                local type_=infer(statement.value,place_type)
            elseif A.Return:isclassof(statement) then
                returned(statement)
            elseif A.Discard:isclassof(statement) then
                infer(statement.value,nil)
            elseif A.If:isclassof(statement) then
                infer(statement.condition,B.Bool); statements(statement.yes); statements(statement.no)
            elseif A.While:isclassof(statement) then
                infer(statement.condition,B.Bool); statements(statement.body)
            elseif A.Switch:isclassof(statement) then
                -- Case labels must be Int or Bool literals (§7.2), so a subject that names a
                -- stage takes that type.
                local label_type
                for _,arm in ipairs(statement.cases) do
                    for _,label in ipairs(arm.labels) do
                        if A.Boolean:isclassof(label) then label_type=label_type or B.Bool
                        else label_type=label_type or B.Int end
                    end
                end
                infer(statement.subject,label_type)
                for _,arm in ipairs(statement.cases) do statements(arm.body) end
                statements(statement.otherwise)
            end
        end
    end

    -- The chain items in source order, then the terminal: a prelude may use an earlier stage,
    -- and the terminal may use any of them.
    for _,item in ipairs(template.source.items) do
        if A.Prelude:isclassof(item) then
            infer_binding(item.binding); chain(item.binding.value,constraint_type(types,item.binding.constraint))
        end
    end
    local terminal=template.source.terminal
    local result
    if A.Body:isclassof(terminal) then
        statements(terminal.statements)
        result=conflict and nil or (returns==0 and B.Unit or stated)
        -- §11.3: a declared `do : T` states the result; it drives callee typing and, through
        -- the entry, is checked against every return. Only a name-form type word is lowered
        -- here; the structural forms arrive with the vocabulary in the build step.
        if terminal.result then
            local declared=constraint_type(types,terminal.result)
            if declared then result=declared end
        end
    elseif A.Data:isclassof(terminal) then
        -- §11.2: a data terminal's type is the type of its terminal expression. That is the
        -- word's result, which is what a `let`-bound word named as a type denotes.
        result=infer(terminal.value,nil)
        -- An aggregate of stages is a constructor: its record carries the constructor's
        -- binding name, so the type is nominal and matches the values the constructor builds.
        if result and A.NamedAggregate:isclassof(terminal.value) and terminal.value.nominal then
            local fields=result:record()
            if fields then result=B.Aggregate(fields,result:copyable(),template.name) end
        end
    end

    return {stages={},result=result}
end

-- A template's contract. `environment` maps a binding to the type the entry packet gave it, so
-- the result a return states can be computed where those types are known. A contract computed
-- without one is remembered, because it describes the template rather than one packet.
function Contract.template(template,resolved,types,environment)
    local general=environment==nil or next(environment)==nil
    if general then
        local cached=memo[template]
        if cached==false then return {stages={},result=nil} end
        if cached then return cached end
        memo[template]=false
    end
    local contract=compute(template,resolved,types,environment or {})
    if general then memo[template]=contract end
    return contract
end

return Contract
end

end)

-- let/scalar.lua
module('let.scalar', function(require, ...)
-- Exact scalar semantics, shared by the concrete test interpreter, compile-time folding, and
-- (through the emitter's own text) the C program, so no two of them can disagree.
--
-- Int and Float arithmetic is the host's own `+`, `-`, `*` and unary `-` on the value the
-- backend uses: LuaJIT's int64 cdata and PUC Lua's integer both wrap exactly as §13.2 requires,
-- and a Float is a binary64. Everything the two hosts spell differently -- truncated division
-- and remainder, bitwise, shifts, conversions, and the C limbs -- comes from `let/host`, so the
-- language's semantics do not depend on which runtime is running the compiler.
local numeric = require('let.numeric')
local literal = require('let.literal')

local M = {}

M.min = numeric.min
M.unit = {}

-- Validates spelling and range, then converts without passing through a Lua number.
function M.integer(spelling, fail)
    local negative = spelling:sub(1, 1) == '-'
    local _, _, hi, lo = literal.integer(negative and spelling:sub(2) or spelling, negative, fail or error)
    return numeric.from_limbs(hi, lo, negative)
end

-- An Int from a host value, for the test interpreter's stage and result conversion.
function M.int64(value) return numeric.from_float(value) end

-- A Float value is a binary64, and this conversion is the one authority for both folding and C
-- emission, so the two cannot round differently.
function M.float(spelling, fail) return literal.float(spelling, fail or error) end

-- Float division is the IEEE operation; a Float32 division rounds the binary64 result back to
-- binary32, so folding and the emitted `float` division agree (DEMAND.md §3).
function M.fdivide(a, b, kind)
    if kind == 'f32' then return numeric.round32(a / b) end
    return a / b
end

-- The two core conversions. `to_float` is total; `to_int` is also total, truncating toward
-- zero and saturating at the Int bounds with a NaN becoming zero, so it stays a pure value
-- operation that can be folded and dropped.
function M.to_float(value) return numeric.to_float(value) end
function M.to_int(value) return numeric.from_float(value) end
-- The fixed-width conversions truncate the low bits of an Int; they are the explicit crossings
-- §13.2 asks for, so no literal or value changes width implicitly.
function M.to_u8(value) return numeric.truncate(8, value) end
function M.to_u32(value) return numeric.truncate(32, value) end
-- A binary64 rounded to the nearest binary32, ties to even (§13.3).
function M.to_f32(value) return numeric.round32(value) end

-- Arithmetic computes the mathematical result, then reduces it modulo 2^width when the type is
-- a fixed-width integer. The width comes from the Let type, never from the host's
-- representation: a nil width is Int (which the host wraps at 64 bits, as §13.2 requires) or
-- Float (where `+ - *` are the binary64 operations).
-- The `kind` is the result type's: 'f32' rounds to binary32, 8/32 reduce modulo 2^width, and
-- nil is Int (the host wraps at 64 bits) or Float (binary64).
function M.add(a, b, kind)
    if kind == 'f32' then return numeric.round32(a + b) end
    if kind then return numeric.truncate(kind, numeric.add(a, b)) end
    return a + b
end
function M.subtract(a, b, kind)
    if kind == 'f32' then return numeric.round32(a - b) end
    if kind then return numeric.truncate(kind, numeric.sub(a, b)) end
    return a - b
end
function M.multiply(a, b, kind)
    if kind == 'f32' then return numeric.round32(a * b) end
    if kind then return numeric.truncate(kind, numeric.mul(a, b)) end
    return a * b
end
function M.negate(a, kind)
    if kind == 'f32' then return numeric.round32(-a) end
    if kind then return numeric.truncate(kind, numeric.neg(a)) end
    return -a
end

-- Division and remainder by zero trap; callers either know the divisor is non-zero (and fold)
-- or must keep a residual checked operation. Truncation and sign come from the backend, because
-- Lua's floor division is not §13.2's.
function M.divide(a, b, width)
    if b == 0 then error('division by zero') end
    local quotient = numeric.div(a, b)
    return width and numeric.truncate(width, quotient) or quotient
end
function M.remainder(a, b, width)
    if b == 0 then error('remainder by zero') end
    local rest = numeric.rem(a, b)
    return width and numeric.truncate(width, rest) or rest
end

function M.equal(a, b) return a == b end
function M.not_equal(a, b) return a ~= b end
function M.less(a, b) return a < b end
function M.less_equal(a, b) return a <= b end
function M.greater(a, b) return a > b end
function M.greater_equal(a, b) return a >= b end

-- Bitwise operations are integer-only and the hosts spell them differently, so they come from
-- the backend and are reduced to the width. §13.2 fixes the semantics: `>>` is arithmetic for
-- Int and logical for the unsigned widths, which for a non-negative fixed-width value is the
-- same operation, and a shift count is reduced modulo the width.
function M.band(a, b, width) local r = numeric.band(a, b); return width and numeric.truncate(width, r) or r end
function M.bor(a, b, width) local r = numeric.bor(a, b); return width and numeric.truncate(width, r) or r end
function M.bxor(a, b, width) local r = numeric.bxor(a, b); return width and numeric.truncate(width, r) or r end
function M.bitnot(a, width) local r = numeric.bnot(a); return width and numeric.truncate(width, r) or r end
function M.shl(a, b, width)
    if width then return numeric.truncate(width, numeric.shl(a, numeric.rem(b, width))) end
    return numeric.shl(a, b)
end
function M.shr(a, b, width)
    if width then return numeric.truncate(width, numeric.shr(a, numeric.rem(b, width))) end
    return numeric.shr(a, b)
end

-- Two's-complement limbs for C emission.
function M.limbs(value) return numeric.to_limbs(value) end

-- The exact decimal of an Int, independent of the host's spelling of its integer type.
function M.int_string(value) return numeric.to_string(value) end

-- The byte length of a Text, shared so a known Text folds and the emitted C reads `.size`.
function M.text_size(value) return #value end

return M

end)

-- let/numeric.lua
module('let.numeric', function(require, ...)
-- The host numeric primitives the compiler needs beyond what Lua gives portably: a signed
-- 64-bit integer value, and rounding a binary64 to binary32. The backend is chosen for the
-- runtime, so nothing above this file names LuaJIT or PUC Lua.
--
-- LuaJIT provides FFI `int64_t` and `float`; PUC Lua 5.3/5.4 provides native 64-bit integers
-- and `string.pack`/`string.unpack`. Lua 5.1 and 5.2 have neither, and are rejected rather than
-- silently miscompiled.
if type(jit) == 'table' then return require('let.numeric_ffi') end
if math and math.maxinteger then return require('let.numeric_native') end
error('Let needs LuaJIT or PUC Lua 5.3+ (a 64-bit integer type)')

end)

-- let/numeric_ffi.lua
module('let.numeric_ffi', function(require, ...)
return load([=[-- The 64-bit integer backend for LuaJIT.
--
-- LuaJIT's FFI `int64_t` already wraps for `+`, `-`, `*` and unary `-` exactly as §13.2
-- requires, and its cdata `/` and `%` already truncate toward zero with the dividend's sign.
-- This file holds the operations LuaJIT does not give directly, and the value construction,
-- so nothing above it depends on FFI.
local ffi = require('ffi')

local M = {}

M.min = ffi.cast('int64_t', 0x8000000000000000ULL)

function M.from_limbs(hi, lo, negative)
    local magnitude = ffi.cast('uint64_t', hi) * 4294967296ULL + lo
    return negative and -ffi.cast('int64_t', magnitude) or ffi.cast('int64_t', magnitude)
end

-- Float to Int: truncate toward zero, saturate at the bounds, and a NaN becomes zero (§13.3).
function M.from_float(value)
    if value ~= value then return ffi.new('int64_t', 0) end
    if value >= 9223372036854775808.0 then return ffi.cast('int64_t', 0x7fffffffffffffffULL) end
    if value < -9223372036854775808.0 then return ffi.cast('int64_t', 0x8000000000000000ULL) end
    return ffi.new('int64_t', value)
end

function M.to_float(value) return tonumber(value) end

-- The exact decimal, with no host spelling: LuaJIT appends `LL` to cdata integers.
function M.to_string(value) return (tostring(value):gsub('LL$','')) end

-- Round a binary64 to the nearest binary32, ties to even, preserving NaN and infinity.
function M.round32(value) return tonumber(ffi.cast('float', value)) end

function M.to_limbs(value)
    local unsigned = ffi.cast('uint64_t', value)
    return tonumber(unsigned / 4294967296ULL), tonumber(unsigned % 4294967296ULL)
end

-- Reduce to the low `width` bits as a non-negative Int. Fixed-width arithmetic computes in
-- 64 bits and then reduces here, so the width is the language's, not the host's.
function M.truncate(width, value)
    if width == 8 then return ffi.cast('int64_t', ffi.cast('uint8_t', value)) end
    return ffi.cast('int64_t', ffi.cast('uint32_t', value))
end

-- Arithmetic wraps identically on both hosts, but the backends expose it so `scalar` never
-- names a host operator directly.
function M.add(a, b) return a + b end
function M.sub(a, b) return a - b end
function M.mul(a, b) return a * b end
function M.neg(a) return -a end

function M.div(a, b) return a / b end
function M.rem(a, b) return a % b end

function M.band(a, b) return a & b end
function M.bor(a, b) return a | b end
function M.bxor(a, b) return a ~ b end
function M.bnot(a) return ~a end

-- A shift count is reduced modulo 64, and `<<` keeps the low 64 bits (§13.2).
function M.shl(a, b)
    return ffi.cast('int64_t', ffi.cast('uint64_t', a) << (ffi.cast('uint64_t', b) % 64))
end

-- LuaJIT's cdata `>>` is logical, so arithmetic is written out: shift the bit pattern, then
-- fill the vacated high bits with the sign bit.
function M.shr(a, b)
    local shift = ffi.cast('uint64_t', b) % 64
    local bits = ffi.cast('uint64_t', a) >> shift
    if a < 0 and shift ~= 0 then bits = bits | ~(ffi.cast('uint64_t', 0xffffffffffffffffULL) >> shift) end
    return ffi.cast('int64_t', bits)
end

return M
]=])()
end)

-- let/numeric_native.lua
module('let.numeric_native', function(require, ...)
return load([=[-- The 64-bit integer backend for PUC Lua 5.3 and 5.4.
--
-- There, an integer is already signed 64-bit and wraps for `+`, `-`, `*` and unary `-`, so the
-- arithmetic needs no help. What differs from §13.2 is spelled out here: Lua's `//` and `%`
-- floor instead of truncating toward zero, `>>` is logical, and a shift count of 64 or more
-- produces zero instead of wrapping.
local M = {}

M.min = math.mininteger

function M.from_limbs(hi, lo, negative)
    local value = hi * 4294967296 + lo
    return negative and -value or value
end

function M.from_float(value)
    if value ~= value then return 0 end
    if value >= 9223372036854775808.0 then return math.maxinteger end
    if value < -9223372036854775808.0 then return math.mininteger end
    local truncated = value < 0 and math.ceil(value) or math.floor(value)
    return math.tointeger(truncated) or 0
end

function M.to_float(value) return value + 0.0 end

function M.to_string(value) return tostring(value) end

-- Round a binary64 to the nearest binary32, ties to even, preserving NaN and infinity.
function M.round32(value) return (string.unpack('<f', string.pack('<f', value))) end

function M.to_limbs(value)
    return (value >> 32) & 0xffffffff, value & 0xffffffff
end

-- Reduce to the low `width` bits. Fixed-width arithmetic computes in 64 bits and then
-- reduces here, so the width is the language's, not the host's.
function M.truncate(width, value)
    if width == 8 then return value & 0xff end
    return value & 0xffffffff
end

function M.add(a, b) return a + b end
function M.sub(a, b) return a - b end
function M.mul(a, b) return a * b end
function M.neg(a) return -a end

-- Truncated division: floor the quotient, then step back toward zero when the signs differ.
function M.div(a, b)
    if a == math.mininteger and b == -1 then return math.mininteger end
    local quotient = a // b
    if a % b ~= 0 and ((a < 0) ~= (b < 0)) then quotient = quotient + 1 end
    return quotient
end

function M.rem(a, b)
    if a == math.mininteger and b == -1 then return 0 end
    return a - M.div(a, b) * b
end

function M.band(a, b) return a & b end
function M.bor(a, b) return a | b end
function M.bxor(a, b) return a ~ b end
function M.bnot(a) return ~a end

function M.shl(a, b) return a << (b & 63) end

function M.shr(a, b)
    local shift = b & 63
    if shift == 0 then return a end
    local bits = a >> shift
    if a < 0 then bits = bits | (~0 << (64 - shift)) end
    return bits
end

return M
]=])()
end)

