-- A Float literal: the grammar has a digit on each side of `.`, and an exponent carries at
-- least one digit. Value and C emission both take their bits from this one conversion, so
-- folding and execution cannot round differently.
local function digits(text)
    return text~='' and text:sub(1,1)~='_' and text:sub(-1)~='_' and not text:find('__',1,true)
        and text:match('^[0-9_]+$')~=nil
end
function M.float(spelling,fail)
    local mantissa,exponent=spelling,nil
    local at=spelling:find('[eE]')
    if at then
        mantissa=spelling:sub(1,at-1); exponent=spelling:sub(at+1)
        local sign=exponent:sub(1,1)
        if sign=='+' or sign=='-' then exponent=exponent:sub(2) end
        if not digits(exponent) then fail('invalid Float spelling') end
    end
    local point=mantissa:find('.',1,true)
    if point then
        if not digits(mantissa:sub(1,point-1)) or not digits(mantissa:sub(point+1)) then fail('invalid Float spelling') end
    elseif not digits(mantissa) then fail('invalid Float spelling') end
    if not point and not at then fail('invalid Float spelling') end
    local value=tonumber((spelling:gsub('_','')))
    if value==nil then fail('invalid Float spelling') end
    return value
end
return M


end)

-- let/packet.lua
module('let.packet', function(require, ...)
-- The word field packet: the ordered bundle of values a word carries between its stages, and
-- the one owner of what a field means.
--
-- A field descriptor is `{name, type, value, mutable, owned, retained, span}` plus whatever the
-- site knows: `capability` for a stage, `definition` for a prelude, `borrows` for a capture. The
-- derived questions -- is it a place, is it owned by the entry, is it written back, what is the
-- entry key -- live here, so the six sites that build a packet and the four that consume one do
-- not each restate them. See DESIGN.md.
return function(V)
local A,B=V.AST,V.Belt

local Packet={}

-- A field that reaches the callee as a place -- an address or a borrow -- is written through,
-- not copied. This is the one place the question is asked.
function Packet.place(type_) return B.Address:isclassof(type_) or B.Borrow:isclassof(type_) end

-- Normalize a descriptor: a site supplies what it knows, and the shared defaults live here.
function Packet.field(spec)
    spec.mutable=spec.mutable==true
    spec.owned=spec.owned==true
    spec.retained=spec.retained==true
    return spec
end

-- A field parameterized into an entry is owned by that entry when it is non-Copy, is not a place,
-- and the word already owned it or its stage takes ownership.
function Packet.entry_owned(field)
    if Packet.place(field.type) or field.type:copyable() then return false end
    return field.owned or A.owns(field.capability)
end

-- The type a stage delivers and who owns it. `mut` and `own mut` reach the callee as a place
-- through a borrow; `own` and `own mut` carry ownership. One rule, so the generic builder and a
-- host entry cannot disagree about what a stage delivers.
function Packet.stage_field(capability,name,span,type_)
    local place=A.places(capability)
    local owned=not type_:copyable() and A.owns(capability)
    return Packet.field{name=name,type=place and B.Borrow(type_,false) or type_,
        mutable=A.places(capability),owned=owned,retained=false,
        span=span,capability=capability,external=place or (not owned and not type_:copyable())}
end

-- The parameter a host entry receives for a stage. The host supplies the value, so there is no
-- field packet here; the shape and the mode are all that matter.
function Packet.stage_parameter(ctx,capability,type_,span)
    local place=A.places(capability)
    local value=ctx:parameter(place and B.Borrow(type_,false) or type_,A.Read)
    if capability==A.Mut then value.mode='mut'
    elseif capability==A.Own or capability==A.OwnMut then value.mode='fresh' end
    return value
end

-- The fields an invocation hands back to the receiver: interior mutable state it can receive. A
-- place is written through the callee itself, so it is never a result.
function Packet.written_back(field)
    return field.mutable and field.retained and not B.Address:isclassof(field.type)
end


-- The entry a field packet names. One key per shape, so call sites that agree share one function
-- and its signature. The per-field flag runs are separate so a shape cannot collide with a longer
-- one that happens to reuse the same type keys.
function Packet.key(template_id,fields)
    local parts={tostring(template_id)}
    for _,field in ipairs(fields) do parts[#parts+1]=field.type:key() end
    for _,field in ipairs(fields) do parts[#parts+1]=field.retained and '1' or '0' end
    for _,field in ipairs(fields) do parts[#parts+1]=field.owned and '1' or '0' end
    return table.concat(parts,'|')
end

-- Bind a field the packet already holds, in the scope the caller opened. A place is bound as its
-- own storage, so the body reaches the caller's value rather than a copy.
function Packet.bind(ctx,field)
    local address=Packet.place(field.value.type) and field.value or false
    ctx:force_bind(field.name,field.value,field.mutable,field.owned,false,address,field.span)
end

function Packet.bind_all(ctx,fields)
    for _,field in ipairs(fields) do Packet.bind(ctx,field) end
end

-- Bind a field as a fresh parameter of an entry, in its own scope. An entry owns a non-Copy,
-- non-place field, and the parameter is what the caller's field becomes here. Returns the binding
-- id, the parameter value and the ownership the entry took, so a caller can record or trace it.
function Packet.bind_parameter(ctx,field,name,span)
    ctx:push(); if field.retained then ctx:retain() end
    local parameter=ctx:parameter(field.type,A.Read)
    if field.capability==A.Mut then parameter.mode='mut'
    elseif field.capability==A.Own or field.capability==A.OwnMut then parameter.mode='fresh' end
    local owned=Packet.entry_owned(field)
    local address=Packet.place(field.type) and parameter or false
    -- The flag `build.lua` reads for a tail-call borrow is "does this binding's storage outlive my
    -- activation". Two things do: a field reached from the caller (`external`), and a *retained*
    -- field, whose storage lives in the word bundle rather than in the frame. A prelude is retained,
    -- so `return c.load_byte(cells, i)` over the word's own prelude is not a dangling borrow and
    -- was wrongly refused.
    local outlives=field.external==true or field.retained==true
    local binding=ctx:force_bind(name or field.name,parameter,field.mutable,owned,outlives,address,span or field.span)
    return binding,parameter,owned
end

return Packet
end

end)

-- let/vocabulary.lua
module('let.vocabulary', function(require, ...)
-- The names a program may refer to and the contracts behind them: the scalar types, the
-- registered resources with their destructors, and the runtime hosts. Validated once, so a call
-- site, an entry and the verifier cannot disagree about a descriptor, and no phase rebuilds the
-- base type table.
return function(V)
local A,B,L=V.AST,V.Belt,V.List

local Vocabulary={}; Vocabulary.__index=Vocabulary

-- One validated vocabulary for a program. A descriptor that is malformed fails here, with the
-- message naming the contract, rather than at whichever consumer happened to read it first.
-- The atomic type names every program has, in one place, so a consumer that must show them
-- (the editor's token classification) does not restate which names are types.
Vocabulary.scalars={'Int','U8','U32','Float','Float32','Bool','Unit','Text','CString','CPointer','Type'}

function Vocabulary.new(options)
    options=options or {}
    local types={Int=B.Int,U8=B.U8,U32=B.U32,Float=B.Float,Float32=B.Float32,Bool=B.Bool,Unit=B.Unit,Text=B.Text,CString=B.CString,CPointer=B.CPointer,Type=B.TypeWord}
    local representations={}
    local destroy={}
    for name,descriptor in pairs(options.resources or {}) do
        assert(type(descriptor.destroy)=='string' and descriptor.destroy:match('^[A-Za-z_][A-Za-z0-9_]*$'),
            'resource requires a destructor symbol')
        if descriptor.representation~=nil then
            assert(descriptor.representation=='pointer' or descriptor.representation=='value',
                'resource representation must be pointer or value')
        end
        types[name]=B.Named(name)
        destroy[name]=descriptor.destroy
        representations[name]=descriptor.representation or 'value'
    end
    local hosts={}
    local symbols={}
    -- The C spelling a host declares must describe its Let type: an integer width for `Int` or a
    -- value resource, an object pointer for a borrowed view or a pointer resource, and
    -- `double`/`bool`/`void` for the rest. This is where the one declaration is checked, rather
    -- than in the C compiler.
    local function compact(name) return (name:gsub('%s','')) end
    local c_integer={}
    for _,name in ipairs{'char','signedchar','unsignedchar','short','unsignedshort','int','unsigned',
        'long','unsignedlong','longlong','unsignedlonglong','size_t','ssize_t','ptrdiff_t','intptr_t',
        'uintptr_t','int8_t','uint8_t','int16_t','uint16_t','int32_t','uint32_t','int64_t','uint64_t'} do
        c_integer[name]=true
    end
    local function c_kind(spelling)
        local c=compact(spelling)
        if c_integer[c] then return 'integer' end
        if c=='double' or c=='float' then return c end
        if c=='bool' or c=='_Bool' then return 'bool' end
        if c=='void' then return 'void' end
        if c:sub(-1)=='*' then return 'pointer' end
        return 'unknown'
    end
    local function compatible(let_type,kind)
        if kind=='integer' then
            -- A C integer describes Int or a fixed-width integer; the width is the Let type's,
            -- not the C spelling's, so the spelling is not matched to a width here.
            return let_type==B.Int or let_type==B.U8 or let_type==B.U32
                or (B.Named:isclassof(let_type) and representations[let_type.name]~='pointer')
        end
        -- §13.3 a C `double` describes Float and a C `float` describes Float32; the two are
        -- never implicitly converted.
        if kind=='double' then return let_type==B.Float end
        if kind=='float' then return let_type==B.Float32 end
        if kind=='bool' then return let_type==B.Bool end
        if kind=='pointer' then
            return let_type==B.CString or let_type==B.CPointer
                or (B.Named:isclassof(let_type) and representations[let_type.name]=='pointer')
        end
        if kind=='void' then return let_type==B.Unit end
        return false
    end
    -- §12.4 The boundary declares the facts C's type system cannot. This table names what each
    -- declaration is for, and a host carrying a field that is not here is refused -- so a field
    -- cannot be added and then quietly ignored. Two are marked as intent only, on purpose:
    -- `ownership` and `nullable` are declared in libc.lua and read by nothing, which reads as a
    -- promise the compiler does not keep. Saying so is the repair; honouring them would need
    -- nullability to be a tracked fact, which is a mechanism this refactor does not add.
    local host_fields={
        symbol='the C symbol the program calls, checked below',
        phase='runtime, checked below',
        purity='pure or ordered, checked below',
        signature='the Let types, checked against the C prototype below',
        c='the C prototype, checked against the signature below',
        helper='an emitted helper rather than a C library symbol (emit.lua)',
        borrows='the argument the result views (build.lua, Context:hold_view)',
        ownership='DECLARED INTENT ONLY -- Let must not free the result. Nothing reads it.',
        nullable='DECLARED INTENT ONLY -- the result may be null. Nothing reads it.',
    }
    local function add_host(name,host)
        for key in pairs(host) do
            assert(host_fields[key],('host %s carries an unclassified field %s'):format(name,tostring(key)))
        end
        assert(host.phase=='runtime' and (host.purity=='ordered' or host.purity=='pure'),
            'host must declare runtime phase and purity')
        assert(type(host.symbol)=='string' and host.symbol:match('^[A-Za-z_][A-Za-z0-9_]*$'),
            'host requires a symbol')
        assert(B.Signature:isclassof(host.signature) and #host.signature.results==1,
            'host requires one Let result')
        if host.c then
            for i,spelling in ipairs(host.c.params or {}) do
                local parameter=host.signature.parameters[i]
                assert(parameter,'the C prototype has more parameters than the Let signature')
                -- A mutable stage is a place, so it is a pointer whatever its pointee is.
                local ok=(parameter.capability==V.AST.Mut and c_kind(spelling)=='pointer')
                    or (parameter.capability~=V.AST.Mut and c_kind(spelling)~='unknown' and compatible(parameter.type,c_kind(spelling)))
                assert(ok,('C type %s does not describe Let parameter %d'):format(spelling,i))
            end
            if host.c.result then
                -- A Unit result discards the C value, so any C result type describes it.
                local result=host.signature.results[1]
                if result~=B.Unit then
                    local kind=c_kind(host.c.result)
                    assert(kind~='unknown' and compatible(result,kind),
                        ('C result %s does not describe the Let result'):format(host.c.result))
                end
            end
        end
        -- The boundary declares ownership and nullability, which C's type system cannot: they
        -- only mean anything for a pointer result.
        if host.ownership~=nil then
            assert(host.ownership=='owned' or host.ownership=='borrowed',
                'host ownership must be owned or borrowed')
        end
        if host.nullable~=nil then
            assert(type(host.nullable)=='boolean','host nullability must be a boolean')
        end
        -- A view of an argument: the result points into storage the caller owns, so the caller's
        -- value must not move or be freed while the view is live. `ownership` says only that Let
        -- must not free the result, which is why the two are declared separately.
        if host.borrows~=nil then
            assert(type(host.borrows)=='number' and host.borrows==math.floor(host.borrows),
                'a host view must name an argument by number')
            assert(host.borrows>=1 and host.borrows<=#host.signature.parameters,
                'a host view must name one of its own arguments')
        end
        if host.ownership~=nil or host.nullable~=nil then
            local result=host.signature.results[1]
            assert(result==B.CString or result==B.CPointer,
                'ownership and nullability apply to a pointer result')
        end
        -- A symbol may be declared twice with the same Let signature: a source `extern` for a
        -- libc name the embedding also registers, for instance. The first declaration wins.
        local existing=symbols[host.symbol]
        if existing then
            local same=#existing.signature.parameters==#host.signature.parameters
                and #existing.signature.results==#host.signature.results
            if same then
                for i,parameter in ipairs(existing.signature.parameters) do
                    local other=host.signature.parameters[i]
                    same=same and parameter.capability==other.capability and parameter.type:same(other.type)
                end
                for i,result in ipairs(existing.signature.results) do same=same and result:same(host.signature.results[i]) end
            end
            assert(same,'host symbol ' .. host.symbol .. ' is declared with two different signatures')
        else
            symbols[host.symbol]=host
        end
        hosts[name]=host
    end
    for name,host in pairs(options.hosts or {}) do add_host(name,host) end
    -- A namespace member is a host too, but it has no top-level name; symbol lookup still needs it.
    for _,namespace in pairs(options.dictionary or {}) do
        for name,member in pairs(namespace.members or {}) do
            if member.signature then add_host(name,member) end
        end
    end
    return setmetatable({types=types,destroy=destroy,representations=representations,
        hosts=hosts,symbols=symbols},Vocabulary)
end

function Vocabulary:type(name) return self.types[name] end
function Vocabulary:host(name) return self.hosts[name] end
function Vocabulary:destructor(name) return self.destroy[name] end
function Vocabulary:representation(name) return self.representations[name] end

-- §11.2: lower a declared type word to its belt type. `nil` means this boundary does not know
-- the name yet -- either an unknown primitive or a `let`-bound type word, which becomes visible
-- when types-as-words resolution lands. Arrow, sum, and record are structural and lower here.
local function flatten_sum(node,into)
    if A.Sum:isclassof(node) then flatten_sum(node.left,into); flatten_sum(node.right,into)
    else into[#into+1]=node end
end
local function lower(self,node)
    if not node then return nil end
    if A.Ref:isclassof(node) then
        if #node.arguments>0 then return nil end
        return self.types[node.name]
    end
    if A.Arrow:isclassof(node) then
        local from,to=lower(self,node.from),lower(self,node.to)
        if not (from and to) then return nil end
        return B.Arrow(from,to)
    end
    if A.Do:isclassof(node) then
        local result=lower(self,node.result)
        if not result then return nil end
        return B.Do(result)
    end
    if A.Sum:isclassof(node) then
        local nodes={}; flatten_sum(node,nodes); local alternatives=L(); local copy=true
        for _,element in ipairs(nodes) do
            local type_=lower(self,element); if not type_ then return nil end
            alternatives:insert(type_); if not type_:copyable() then copy=false end
        end
        return B.Sum(alternatives,copy)
    end
    if A.Record:isclassof(node) then
        local fields,complete=L(),true
        for _,field in ipairs(node.fields) do
            local type_=lower(self,field.type)
            if not type_ then complete=false else fields:insert(B.Field(field.name,type_,field.mutable)) end
        end
        if not complete then return nil end
        local copy=true
        for _,field in ipairs(fields) do if field.mutable or not field.type:copyable() then copy=false end end
        return B.Aggregate(fields,copy,nil)
    end
    if A.Tuple:isclassof(node) then
        local fields,complete=L(),true
        for _,element in ipairs(node.elements) do
            local type_=lower(self,element)
            if not type_ then complete=false else fields:insert(B.Field(nil,type_,false)) end
        end
        if not complete then return nil end
        local copy=true
        for _,field in ipairs(fields) do if not field.type:copyable() then copy=false end end
        return B.Aggregate(fields,copy,nil)
    end
    -- A type-word application (e.g. `List Int`) needs a type constructor, which is not yet a
    -- value; it lowers to nothing until types-as-words lands.
    return nil
end
function Vocabulary:resolve_type(node) return lower(self,node) end

return Vocabulary
end

end)

-- let/libc.lua
module('let.libc', function(require, ...)
-- The C library the command-line host offers under the `c` namespace, so a Let program can call
-- libc with no hand-written host. Each entry states the Let signature the frontend checks, the C
-- prototype the emitter spells where a C type is not the Let type's natural mapping (§15.3), and
-- the ownership and nullability the boundary declares (spec §12.4).
--
-- `CString` is a borrowed `const char*` and `CPointer` an opaque `void*`; both are types of their
-- own rather than `Text`, and `c.string` / `c.text` are the explicit crossings.
--
-- Owned C memory is a `resource` whose C representation is a pointer (`CAlloc`), so Let owns it
-- and destroys it exactly once with `free`; there is no `c.free` to call. A foreign call that
-- mutates the bytes behind the pointer does so outside Let's invariants, which is why those calls
-- are `ordered`.
--
-- The set is deliberately small and sound at the Let type level: string, integer and byte
-- functions, no variadic form (`printf`), and no dereference or pointer arithmetic. Those need a
-- surface the specification does not define yet, and inventing one here would be a language
-- decision, not a vocabulary.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
local int=B.Parameter(B.Int,A.Read)
local cstring=B.Parameter(B.CString,A.Read)
local allocation=B.Parameter(B.Named('CAlloc'),A.Read)

local function word(symbol,purity,signature,extra)
    local descriptor={symbol=symbol,phase='runtime',purity=purity,signature=signature}
    for key,value in pairs(extra or {}) do descriptor[key]=value end
    return descriptor
end
local function ordered(symbol,signature,extra) return word(symbol,'ordered',signature,extra) end
local function pure(symbol,signature,extra) return word(symbol,'pure',signature,extra) end

return {
    -- A pointer-shaped resource: owned by Let, destroyed by `free`, never dereferenced by Let.
    resources={CAlloc={destroy='free',representation='pointer'}},
    members={
        -- The explicit crossings between a Let Text and a borrowed C string.
        string={phase='runtime',conversion='cstring'},
        text={phase='runtime',conversion='ctext'},
        -- The byte length of a Text, and a null test for a borrowed pointer.
        byte_length={phase='runtime',conversion='byte_length'},
        null={phase='runtime',conversion='null'},
        -- A Text view over a borrowed pointer and a length, so a read buffer becomes a Text.
        text_of={phase='runtime',conversion='text_of'},

        puts=ordered('puts',B.Signature(L{cstring},L{B.Int}),{c={result='int'}}),
        putchar=ordered('putchar',B.Signature(L{int},L{B.Int}),{c={params={'int'},result='int'}}),
        strlen=pure('strlen',B.Signature(L{cstring},L{B.Int}),{c={result='size_t'}}),
        strcmp=pure('strcmp',B.Signature(L{cstring,cstring},L{B.Int}),{c={result='int'}}),
        atoi=pure('atoi',B.Signature(L{cstring},L{B.Int}),{c={result='int'}}),
        llabs=pure('llabs',B.Signature(L{int},L{B.Int}),{c={params={'long long'},result='long long'}}),
        getenv=pure('getenv',B.Signature(L{cstring},L{B.CString}),
            {c={result='char *'},ownership='borrowed',nullable=true}),

        -- C memory. The allocation is the owner; `memset`/`memcpy`/`memcmp` borrow it.
        malloc=ordered('malloc',B.Signature(L{int},L{B.Named('CAlloc')}),
            {c={params={'size_t'},result='void *'}}),
        memset=ordered('memset',B.Signature(L{allocation,int,int},L{B.CPointer}),
            {c={params={'void *','int','size_t'},result='void *'}}),
        memcpy=ordered('memcpy',B.Signature(L{allocation,cstring,int},L{B.CPointer}),
            {c={params={'void *','const void *','size_t'},result='void *'}}),
        memcmp=pure('memcmp',B.Signature(L{allocation,cstring,int},L{B.Int}),
            {c={params={'const void *','const void *','size_t'},result='int'}}),
        -- A file descriptor reads into an owned allocation and writes a borrowed Text view; the
        -- count comes from `c.byte_length`, so no terminator is assumed.
        write=ordered('write',B.Signature(L{int,cstring,int},L{B.Int}),
            {c={params={'int','const void *','size_t'},result='long'}}),
        -- Byte and binary32 buffers: `CAlloc` is the owned buffer, the index is a runtime Int,
        -- and the emitter supplies these helpers, so no external runtime is needed. A read is
        -- ordered because the bytes behind the pointer can change between calls.
        load_byte=ordered('let_load_byte',B.Signature(L{allocation,int},L{B.Int}),
            {c={params={'void *','int64_t'},result='int64_t'},helper='buffer'}),
        store_byte=ordered('let_store_byte',B.Signature(L{allocation,int,int},L{B.Unit}),
            {c={params={'void *','int64_t','int64_t'},result='void'},helper='buffer'}),
        load_f32=ordered('let_load_f32',B.Signature(L{allocation,int},L{B.Float32}),
            {c={params={'void *','int64_t'},result='float'},helper='buffer'}),
        store_f32=ordered('let_store_f32',B.Signature(L{allocation,int,B.Parameter(B.Float32,A.Read)},L{B.Unit}),
            {c={params={'void *','int64_t','float'},result='void'},helper='buffer'}),
        read=ordered('read',B.Signature(L{int,allocation,int},L{B.Int}),
            {c={params={'int','void *','size_t'},result='long'}}),
    },
}
end

end)

-- let/extern.lua
module('let.extern', function(require, ...)
-- Source `extern` declarations become ordinary host descriptors, so a pure Let file can call a C
-- function with no embedding registration. The declaration states the Let signature; the C
-- prototype is derived from it, and a Text argument on a type states the exact C spelling where
-- the natural mapping is not what the function wants -- `Int "size_t"`, `CString "const void *"`.
--
-- This is the producer side of spec §12.4, and it produces the very descriptor a Lua options file
-- would have written, so resolution, construction and emission see one vocabulary.
return function(V)
local A,B,L=V.AST,V.Belt,V.List
-- `V.Lexer` is loaded after this module, so the diagnostic is looked up when it is used.
local function fail(span,message) V.Lexer.fail(span,message) end

local Extern={}

-- The C spelling a Let type maps to when the declaration does not state one.
local function natural(type_,representations)
    if type_==B.Int then return 'int64_t' end
    if type_==B.Float then return 'double' end
    if type_==B.Bool then return 'bool' end
    if type_==B.Unit then return 'void' end
    if type_==B.CString then return 'const char*' end
    if type_==B.CPointer then return 'void*' end
    if B.Named:isclassof(type_) then
        return representations[type_.name]=='pointer' and 'void*' or 'int64_t'
    end
end

-- Merge every `extern` declaration in `file` into `options.hosts`, so resolution, construction
-- and emission all see one vocabulary.
function Extern.merge(file,options)
    local hosts=options.hosts or {}
    local types={Int=B.Int,Float=B.Float,Bool=B.Bool,Unit=B.Unit,Text=B.Text,CString=B.CString,CPointer=B.CPointer}
    local representations={}
    for name,descriptor in pairs(options.resources or {}) do
        types[name]=B.Named(name)
        representations[name]=descriptor.representation or 'value'
    end
    -- A constraint is a Let type, optionally followed by a Text naming its exact C spelling.
    local function declared(constraint,span,message)
        if not constraint then return nil,nil end
        local type_=types[constraint.name]
        if not type_ then fail(span,message .. ' ' .. constraint.name) end
        local spelling
        if #constraint.arguments>0 then
            local argument=constraint.arguments[1]
