        local mantissa=rest:match('^%d[%d_]*%.%d[%d_]*')
        if mantissa then
            local exponent=rest:sub(#mantissa+1):match('^[eE][%+%-]?%d[%d_]*')
            if not exponent and rest:sub(#mantissa+1):match('^[eE]') then
